SET NAMES utf8mb4;
SET time_zone = '+00:00';

-- DealerOps demo seed: sales_lead and sales_lead_note.
-- Generated by dealer-platform/seed/scripts/gen_leads.py; do not hand-edit.
--
-- Natural keys:
--   dealer   : dealer.contact_email
--   customer : (dealer_id, customer.email)
--   vehicle  : (dealer_id, vehicle.vin)
--   lead     : (dealer_id, created_at). Every seeded lead of a dealership has a distinct
--              created_at, so this pair identifies the lead for its notes and for re-runs.
--   note     : (lead_id, created_at)
-- WON leads point at a SOLD vehicle. Their customer is the buyer linked in customer_vehicle
-- (03_customers_links.sql) when one exists, otherwise the planned contract customer.
-- Open leads reference IN_STOCK vehicles only (LEAD-02); WON/LOST leads have no follow-up date;
-- LOST leads carry a reason (LEAD-03); owners are dealership staff with a membership (LEAD-04).
-- Every insert is guarded with WHERE NOT EXISTS, so re-running the file adds nothing.

-- D01
SET @d = (SELECT id FROM dealer WHERE contact_email = 'sales@lakeshoreautosales.ca');
SET @v = (SELECT id FROM vehicle WHERE dealer_id = @d AND vin = '3MZBM1L75FM193583');
SET @c = COALESCE((SELECT customer_id FROM customer_vehicle WHERE dealer_id = @d AND vehicle_id = @v), (SELECT id FROM customer WHERE dealer_id = @d AND email = 'elenanguyen32@icloud.com'));
INSERT INTO sales_lead (dealer_id, customer_id, vehicle_id, owner_username, stage, next_follow_up_on, lost_reason, version, created_at, updated_at)
SELECT @d, @c, @v, 'wei.morrison', 'WON', NULL, NULL, 3, '2026-02-02 14:00:10', '2026-02-11 19:48:23'
FROM DUAL WHERE @d IS NOT NULL AND @c IS NOT NULL AND @v IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM sales_lead WHERE dealer_id = @d AND created_at = '2026-02-02 14:00:10');
SET @l = (SELECT id FROM sales_lead WHERE dealer_id = @d AND created_at = '2026-02-02 14:00:10');
